/**
 * Sites Worker config for CI.
 *
 * `freebuff.open-next.config.ts` at the repository root is generated by Freebuff
 * Sites and gitignored, so a CI checkout has nothing for
 * `scripts/smoke-worker.mjs --sites` to build with. This committed file names
 * the same three overrides the generated config names — the R2 incremental
 * cache, the Durable Object queue and the sharded DO tag cache — so CI can build
 * the Sites Worker and run the smoke check that proves the OCR model rewrite and
 * its digest, instead of discovering a rewrite regression at publish time.
 *
 * It is a **build input for the smoke check, not a deployment config**: the
 * publish path uses the platform's generated file and its real bindings, and
 * nothing here is uploaded. Keep the overrides in step with the generated file;
 * `tests/worker-smoke-sites-mode.test.ts` pins them so a drift is a failing test
 * rather than a CI pass that no longer resembles what ships.
 */
import { defineCloudflareConfig } from "@opennextjs/cloudflare";
import r2 from "@opennextjs/cloudflare/overrides/incremental-cache/r2-incremental-cache";
import queue from "@opennextjs/cloudflare/overrides/queue/do-queue";
import tags from "@opennextjs/cloudflare/overrides/tag-cache/do-sharded-tag-cache";

export default defineCloudflareConfig({
  incrementalCache: r2,
  queue,
  tagCache: tags({ baseShardSize: 4 }),
});
